package com.jnapanam.sportszone.content.model;import jakarta.persistence.*;import java.time.Instant;import java.util.*;
@Entity@Table(name="content_pages")public class ContentPage{@Id private UUID id;@Column(nullable=false,unique=true,length=80)private String slug;@Column(nullable=false,length=180)private String title;@Column(length=500)private String summary;@Column(nullable=false,columnDefinition="TEXT")private String body;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private ContentStatus status;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected ContentPage(){}public ContentPage(String s,String t,String summary,String body){id=UUID.randomUUID();slug=s.trim().toLowerCase(Locale.ROOT);update(t,summary,body,ContentStatus.DRAFT);}public void update(String t,String s,String b,ContentStatus status){title=t.trim();summary=clean(s);body=b.trim();this.status=status;updatedAt=Instant.now();}public UUID getId(){return id;}public String getSlug(){return slug;}public String getTitle(){return title;}public String getSummary(){return summary;}public String getBody(){return body;}public ContentStatus getStatus(){return status;}public Instant getUpdatedAt(){return updatedAt;}private static String clean(String v){return v==null||v.isBlank()?null:v.trim();}}
